window.exportJmsToCsv = function() {
  const data = (filteredDataset && filteredDataset.length > 0) ? filteredDataset : (commercialJmsData || []);
  const headers = isJmsColumnsExpanded ? [
    "PO No",
    "Project ID",
    "Site Name",
    "Site ID",
    "Project Type",
    "Sub-Project Type",
    "Task",
    "Support Required",
    "Pending With",
    "Remarks",
    "Ageing",
    "Amount"
  ] : [
    "PO No",
    "Project ID",
    "Site Name",
    "Site ID",
    "Project Type",
    "Sub-Project Type",
    "Task",
    "Ageing",
    "Amount"
  ];

  const escapeCsv = (str) => {
    if (str === null || str === undefined) return '""';
    const s = String(str).replace(/"/g, '""');
    return `"${s}"`;
  };

  const rows = data.map(r => {
    if (isJmsColumnsExpanded) {
      return [
        escapeCsv(r.poNo),
        escapeCsv(r.projectId),
        escapeCsv(r.siteName),
        escapeCsv(r.siteId),
        escapeCsv(r.projectType),
        escapeCsv(r.subProjectType),
        escapeCsv(r.task),
        escapeCsv(r.supportRequired),
        escapeCsv(r.pendingWith),
        escapeCsv(r.remarks),
        escapeCsv(r.ageing),
        escapeCsv(r.amount)
      ].join(',');
    } else {
      return [
        escapeCsv(r.poNo),
        escapeCsv(r.projectId),
        escapeCsv(r.siteName),
        escapeCsv(r.siteId),
        escapeCsv(r.projectType),
        escapeCsv(r.subProjectType),
        escapeCsv(r.task),
        escapeCsv(r.ageing),
        escapeCsv(r.amount)
      ].join(',');
    }
  });

  const csvContent = [headers.join(','), ...rows].join('\r\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `JMS_Worklist_${new Date().toISOString().slice(0, 10)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
  showToast('JMS CSV downloaded successfully!');
};

