function setExpenseFormReadOnly(isReadOnly, isEditModeOnly = false) {
  const form = document.getElementById('frmAddExpense');
  if (!form) return;
  // In edit mode, ONLY GST, RCM, and Status are editable
  const editableInEditModeIds = [
    'inpExpenseGst'
  ];
  const inputs = form.querySelectorAll('input, select');
  inputs.forEach(input => {
    if (input.type === 'checkbox') return;
    if (isReadOnly) {
      if (input.tagName === 'SELECT') input.setAttribute('disabled', 'true');
      else input.setAttribute('readonly', 'true');
      input.style.backgroundColor = '#f8fafc';
    } else {
      if (isEditModeOnly) {
        if (editableInEditModeIds.includes(input.id)) {
          if (input.tagName === 'SELECT') input.removeAttribute('disabled');
          else input.removeAttribute('readonly');
          input.style.backgroundColor = '#ffffff';
        } else {
          if (input.tagName === 'SELECT') input.setAttribute('disabled', 'true');
          else input.setAttribute('readonly', 'true');
          input.style.backgroundColor = '#f8fafc';
        }
      } else {
        if (input.tagName === 'SELECT') input.removeAttribute('disabled');
        else input.removeAttribute('readonly');
        input.style.backgroundColor = '#ffffff';
      }
    }
  });
  const toggles = form.querySelectorAll('input[type="checkbox"]');
  toggles.forEach(t => {
    t.disabled = isReadOnly;
    const parentSwitch = t.closest('.toggle-slide-switch') || t.closest('.form-toggle-wrap') || t.closest('label');
    if (parentSwitch) {
      parentSwitch.style.pointerEvents = isReadOnly ? 'none' : 'auto';
      parentSwitch.style.opacity = isReadOnly ? '0.65' : '1';
    }
  });
}

window.openViewExpenseCard = async function(expenseId) {
  let exp = masterExpensesData.find(e => String(e.id) === String(expenseId) || String(e.expense_id) === String(expenseId) || e.expenseHead === expenseId || e.expenseName === expenseId);
  if (!exp && typeof NexusApi !== 'undefined' && NexusApi.expenses) {
    try {
      exp = await NexusApi.expenses.getById(expenseId);
    } catch (e) {
      console.warn('Could not fetch expense by ID from API', e);
    }
  }

  if (!exp) {
    showToast('Expense record not found.');
    return;
  }

  currentViewedExpenseId = exp.id || exp.expense_id;
  isExpenseFormEditing = false;

  const overlay = document.getElementById('sideFormOverlay');
  if (overlay) overlay.style.display = 'flex';

  const cards = document.querySelectorAll('.side-form-card');
  cards.forEach(c => c.style.display = 'none');

  const card = document.getElementById('addExpenseCard');
  if (card) card.style.display = 'block';

  const lblTitle = document.getElementById('lblExpenseCardTitle');
  if (lblTitle) lblTitle.innerText = 'View Expense';

  const btnEditToggle = document.getElementById('btnExpenseCardEditToggle');
  const imgEditIcon = document.getElementById('imgExpenseCardEditIcon');
  if (btnEditToggle) btnEditToggle.style.display = 'flex';
  if (imgEditIcon) {
    imgEditIcon.src = 'icons/Edit.svg';
    imgEditIcon.title = 'Edit Info';
  }

  const btnSaveWrap = document.querySelector('#frmAddExpense .form-submit-inside-wrap');
  if (btnSaveWrap) btnSaveWrap.style.display = 'none';

  if (document.getElementById('inpExpenseName')) document.getElementById('inpExpenseName').value = exp.expenseName || exp.expense_name || exp.expenseDescription || exp.expenseHead || '';
  if (document.getElementById('inpExpenseCategory')) document.getElementById('inpExpenseCategory').value = exp.expenseCategory || exp.expense_category || 'Direct Operations';
  if (document.getElementById('inpExpenseSubCategory')) document.getElementById('inpExpenseSubCategory').value = exp.expenseSubCategory || exp.expense_sub_category || exp.expense_description || 'Civil Works';
  if (document.getElementById('inpExpenseHead')) {
    document.getElementById('inpExpenseHead').value = exp.expenseHead || exp.expense_head || 'Capex';
    if (typeof handleExpenseHeadChange === 'function') {
      handleExpenseHeadChange();
    }
  }
  if (document.getElementById('inpExpenseGst')) document.getElementById('inpExpenseGst').value = exp.gst || (exp.gst_rate != null ? exp.gst_rate + '%' : '18%');
  if (document.getElementById('inpExpenseDepreciation')) document.getElementById('inpExpenseDepreciation').value = exp.depreciation_rate || exp.depreciation || '10%';

  const rcmToggle = document.getElementById('inpExpenseRcmToggle');
  if (rcmToggle) {
    rcmToggle.checked = (String(exp.rcm || '').toLowerCase() === 'yes' || exp.rcm === true);
  }

  const statusToggle = document.getElementById('inpExpenseStatusToggle');
  if (statusToggle) {
    statusToggle.checked = (String(exp.status || '').toLowerCase() === 'active' || exp.status === true);
  }

  setExpenseFormReadOnly(true);
  showToast(`Viewing expense details: ${exp.expenseName || exp.expense_name || exp.expenseHead || ''}`);
};

function exportToCsv() {
  let headers = [];
  let rows = [];

  if (currentModule === 'indus_towers') {
    if (currentIndusSubpage === 'infra') {
      headers = ["Infra Category", "Infra Description", "Uom", "Make", "Commissioning", "I - Map", "Status"];
      rows = filteredDataset.map(r => [
        r.infra_category || r.infraCategory || '',
        r.infra_description || r.infraDescription || '',
        r.uom || '',
        r.make || '',
        r.commissioning || '',
        r.i_map || r.iMap || '',
        r.status || ''
      ]);
    } else if (currentIndusSubpage === 'products') {
      headers = ["Item Code", "Product Name", "Product Type", "Product Description", "HSN / SAC Type", "HSN / SAC Code", "Active Rate", "Budget %", "Budget Amount", "Status"];
      rows = filteredDataset.map(r => [r.itemCode, r.productName, r.productType, r.productDescription, r.hsnSacType, r.hsnSacCode, r.activeRate, r.budgetPercent, r.budgetAmount, r.status]);
    } else if (currentIndusSubpage === 'esh') {
      headers = ["Name", "Employee Type", "Aadhar Number", "Training Type", "Training ID Number", "Training Agency", "Expiry Date", "Status"];
      rows = filteredDataset.map(r => [
        r.name || '',
        r.employee_type || r.employeeType || '',
        r.aadhar_number || r.aadharNumber || '',
        r.training_type || r.trainingType || '',
        r.training_id_number || r.trainingIdNumber || '',
        r.training_agency || r.trainingAgency || '',
        r.expiry_date || r.expiryDate || '',
        r.status || 'Active'
      ]);
    } else {
      headers = ["Circle", "Site ID", "WH ID", "Site Name", "District", "Town", "Lattitude", "Longtitude", "Transport Zone", "Status"];
      rows = filteredDataset.map(r => [r.circle, r.siteId, r.whId, r.siteName, r.district, r.town, r.latitude, r.longitude, r.transportZone, r.status]);
    }
  } else if (currentModule === 'master') {
    if (currentMasterSubpage === 'customer') {
      headers = ["Business Type", "Customer ID", "Customer Name", "GST Number", "GST Type", "Invoice Type", "Status"];
      rows = filteredDataset.map(r => [r.businessType, r.customerId, r.customerName, r.gstNumber, r.gstType, r.invoiceType, r.status]);
    } else if (currentMasterSubpage === 'vendor') {
      headers = ["Vendor Name", "Business Type", "Service Type", "GST Number", "PAN Number", "GST Type", "Status"];
      rows = filteredDataset.map(r => [r.vendorName, r.businessType || r.vendorType, r.serviceType, r.gstNumber, r.panNumber, r.gstType, r.status]);
    } else if (currentMasterSubpage === 'products') {
      headers = ["Product Head", "Product Code", "HSN Code", "Product Description", "GST Rate", "Status"];
      rows = filteredDataset.map(r => [r.productHead, r.productCode, r.hsnCode, r.productDescription, r.gstRate, r.status]);
    } else if (currentMasterSubpage === 'expenses') {
      headers = ["Expense Head", "Expense Code", "SAC Code", "Expense Description", "TDS Rate", "GST Rate", "Uom", "Status"];
      rows = filteredDataset.map(r => [r.expenseHead, r.expenseCode, r.sacCode, r.expenseDescription, r.tdsRate, r.gstRate, r.uom, r.status]);
    } else if (currentMasterSubpage === 'transport') {
      headers = ["Transport Name", "Transport Type", "Vehicle Type", "Vehicle Number", "Status"];
      rows = filteredDataset.map(r => [r.transportName, r.transportType, r.vehicleType, r.vehicleNumber, r.status]);
    } else if (currentMasterSubpage === 'employee') {
      headers = ["Employee ID", "Employee Name", "Designation", "Contact Number", "E-Mail", "Status"];
      rows = filteredDataset.map(r => [r.employeeId, r.employeeName, r.designation, r.contactNumber, r.email, r.status]);
    } else {
      headers = Object.keys(filteredDataset[0] || {}).filter(k => k !== 'id');
      rows = filteredDataset.map(r => headers.map(h => r[h]));
    }
  } else if (currentModule === 'infra_wh') {
    if (currentInfraWhSubpage === 'stn') {
      headers = ["STN No", "STN Date", "BOQ No", "BOQ Date", "Project ID", "Site Name", "Infra Category", "Qty", "Status", "Received By", "Ageing", "Remarks"];
      rows = filteredDataset.map(r => [
        r.stnNo || '',
        r.stnDate || '',
        r.boqNo || '',
        r.boqDate || '',
        r.projectId || '',
        r.siteName || '',
        r.infraCategory || '',
        r.qty || '',
        r.status || '',
        r.receivedBy || '',
        r.ageing || '',
        r.remarks || ''
      ]);
    } else if (currentInfraWhSubpage === 'srn') {
      headers = ["SRN No", "SRN Date", "GE No", "GE Date", "BOQ No", "BOQ Date", "Project ID", "Site Name", "Infra Category", "Qty", "Status", "Received By", "Ageing", "Remarks"];
      rows = filteredDataset.map(r => [
        r.srnNo || '',
        r.srnDate || '',
        r.geNo || '',
        r.geDate || '',
        r.boqNo || '',
        r.boqDate || '',
        r.projectId || '',
        r.siteName || '',
        r.infraCategory || '',
        r.qty || '',
        r.status || '',
        r.receivedBy || '',
        r.ageing || '',
        r.remarks || ''
      ]);
    } else {
      headers = [];
      rows = [];
    }
  } else if (currentWorklistView === 'po') {
    headers = ["Submission Date", "Submitted BY", "Vendor Name", "PO No", "PO Amount"];
    rows = filteredDataset.map(r => [r.submissionDate, r.submittedBy, r.vendorName, r.poNo, r.poAmount]);
  } else {
    headers = ["Submit By", "Submission Date", "Approved By", "Expense Head", "Transfer To", "Approved Amount", "Transferred Amount", "Payable Amount", "Ageing"];
    rows = filteredDataset.map(r => [r.submitBy, r.submissionDate, r.approvedBy, r.expenseHead, r.transferTo, r.approvedAmount, r.transferredAmount, r.payableAmount, r.ageing]);
  }

  let csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), ...rows.map(e => e.map(val => `"${String(val ?? '').replace(/"/g, '""')}"`).join(","))].join("\n");
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  const subpageName = currentModule === 'infra_wh' ? currentInfraWhSubpage : (currentIndusSubpage || currentMasterSubpage || currentWorklistView || 'export');
  link.setAttribute("download", `nexus_${currentModule}_${subpageName}_${Date.now()}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  showToast(`Exported ${subpageName.toUpperCase()} to CSV successfully!`);
}

