let toastTimeout = null;
function showToast(message) {
  const toast = document.getElementById('homeToast');
  if (!toast) return;

  toast.textContent = message;
  toast.classList.add('show');

  if (toastTimeout) clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => {
    toast.classList.remove('show');
  }, 3500);
}

// ==========================================================================
// 10. CSV & PDF NATIVE FILE UPLOAD ENGINE (Filters strictly .csv and .pdf)
// ==========================================================================
function triggerCsvUpload() {
  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = '.csv, .xlsx, .xls, text/csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel';
  fileInput.style.display = 'none';

  fileInput.addEventListener('change', async (e) => {
    const file = e.target.files[0];
    if (file) {
      const fileName = file.name;
      const ext = fileName.split('.').pop().toLowerCase();
      if (ext !== 'csv' && ext !== 'xlsx' && ext !== 'xls') {
        showToast('Invalid file format. Please select a .csv or .xlsx file');
        return;
      }
      if (typeof currentModule !== 'undefined' && currentModule === 'master' && typeof currentMasterSubpage !== 'undefined' && currentMasterSubpage === 'expenses' && typeof NexusApi !== 'undefined' && NexusApi.expenses) {
        try {
          showToast(`Uploading "${fileName}" to PostgreSQL...`);
          const result = await NexusApi.expenses.bulkUpload(file);
          showToast(`Bulk upload successful: ${result.imported_count || 0} expenses imported!`);
          if (typeof loadMasterExpensesFromApi === 'function') {
            await loadMasterExpensesFromApi();
          }
        } catch (err) {
          console.error('Bulk upload error:', err);
          showToast(`Bulk upload failed: ${err.message || err}`);
        }
      } else {
        showToast(`File "${fileName}" uploaded successfully!`);
      }
    }
  });

  document.body.appendChild(fileInput);
  fileInput.click();
  setTimeout(() => {
    if (document.body.contains(fileInput)) {
      document.body.removeChild(fileInput);
    }
  }, 1000);
}

function triggerPdfUpload(targetInput) {
  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = '.pdf, application/pdf';
  fileInput.style.display = 'none';

  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      const fileName = file.name;
      const ext = fileName.split('.').pop().toLowerCase();
      if (ext !== 'pdf') {
        showToast('Invalid file format. Please select a .pdf file');
        return;
      }
      if (targetInput) {
        if (typeof targetInput === 'string') {
          const el = document.getElementById(targetInput);
          if (el) el.value = fileName;
        } else if (targetInput instanceof HTMLElement) {
          targetInput.value = fileName;
        }
      }
      showToast(`PDF Document "${fileName}" uploaded successfully!`);
    }
  });

  document.body.appendChild(fileInput);
  fileInput.click();
  setTimeout(() => {
    if (document.body.contains(fileInput)) {
      document.body.removeChild(fileInput);
    }
  }, 1000);
}

function getCurrentBulkPageLabel() {
  if (typeof currentModule !== 'undefined' && currentModule === 'worklist') {
    if (typeof currentWorklistView !== 'undefined') {
      if (currentWorklistView === 'po_amend' || currentWorklistView === 'po_amend_detail') return 'PO Amend';
      if (currentWorklistView === 'wcc') return 'WCC';
      if (currentWorklistView === 'new_project') return 'New project';
      if (currentWorklistView === 'jms' || currentWorklistView === 'jms_detail') return 'JMS';
    }
    return 'New project';
  }
  if (typeof currentModule !== 'undefined' && currentModule === 'master') {
    if (currentMasterSubpage === 'products') return 'Products';
    if (currentMasterSubpage === 'expenses') return 'Expense';
    if (currentMasterSubpage === 'transport') return 'Transport';
    return 'Employee';
  }
  if (typeof currentModule !== 'undefined' && (currentModule === 'indus' || currentModule === 'indus_towers' || currentModule === 'customer')) {
    if (currentIndusSubpage === 'product_details') {
      if (currentIndusProductSubpage === 'materials') return 'Materials';
      if (currentIndusProductSubpage === 'expenses') return 'Expenses';
    }
    if (currentIndusSubpage === 'products') return 'GBPA';
    if (currentIndusSubpage === 'infra') return 'Infra';
    if (currentIndusSubpage === 'site') return 'Site';
  }
  if (typeof currentWorklistView !== 'undefined') {
    if (currentWorklistView === 'po_amend' || currentWorklistView === 'po_amend_detail') return 'PO Amend';
    if (currentWorklistView === 'wcc') return 'WCC';
    if (currentWorklistView === 'new_project') return 'New project';
    if (currentWorklistView === 'receivable') return 'Receivable';
    if (currentWorklistView === 'po_to_be_open') return 'PO to be Open';
  }
  return 'Employee';
}

function triggerBulkUpload() {
  const pageLabel = getCurrentBulkPageLabel();
  openBulkUploadModal(pageLabel);
}

// Global click delegation for PDF upload badges, CSV upload, and Bulk upload buttons
document.addEventListener('click', (e) => {
  const pdfBadge = e.target.closest('.input-pdf-badge');
  if (pdfBadge) {
    e.preventDefault();
    const parentWrap = pdfBadge.closest('.form-input-wrap');
    const associatedInput = parentWrap ? parentWrap.querySelector('input') : null;
    triggerPdfUpload(associatedInput);
    return;
  }

  const csvBtn = e.target.closest('.btn-csv-action, #btnIndusCsv, #btnMasterCsv, #btnCsvAction');
  if (csvBtn) {
    e.preventDefault();
    triggerCsvUpload();
    return;
  }

  const bulkBtn = e.target.closest('.btn-doc-upload-action, #btnIndusDocUpload, #btnMasterDocUpload');
  if (bulkBtn) {
    const onclickAttr = bulkBtn.getAttribute('onclick') || '';
    const match = onclickAttr.match(/openBulkUploadModal\(['"]([^'"]+)['"]\)/);
    if (match && match[1]) {
      e.preventDefault();
      openBulkUploadModal(match[1]);
      return;
    }
    e.preventDefault();
    triggerBulkUpload();
    return;
  }
});

