let jmsDocumentsMap = {};

function getDefaultJmsDocuments(key) {
  return [
    {
      id: `jmsdoc-${Date.now()}-1`,
      docType: 'STN Document',
      docDetails: 'Site Transfer Note Sign-off',
      docName: 'STN_Document_Signed.pdf',
      selected: false
    },
    {
      id: `jmsdoc-${Date.now()}-2`,
      docType: 'Commissioning Report',
      docDetails: 'Site Commissioning & Handover',
      docName: 'Commissioning_Report_v1.pdf',
      selected: false
    },
    {
      id: `jmsdoc-${Date.now()}-3`,
      docType: 'Approved JMS',
      docDetails: 'Approved Joint Measurement Sheet',
      docName: 'Approved_JMS_Copy.pdf',
      selected: false
    }
  ];
}

function getJmsDocuments(rowId) {
  const key = rowId || (typeof selectedJmsRowId !== 'undefined' && selectedJmsRowId) || 'default';
  if (!jmsDocumentsMap[key]) {
    jmsDocumentsMap[key] = getDefaultJmsDocuments(key);
  }
  return jmsDocumentsMap[key];
}

window.openJmsDocumentsModal = async function() {
  const overlay = document.getElementById('sideFormOverlay');
  const panel = document.getElementById('jmsDocumentsPanel');
  const addCard = document.getElementById('addJmsDocumentCard');
  if (!overlay || !panel) return;

  // Hide all other side cards in overlay
  document.querySelectorAll('.side-form-card').forEach(card => card.style.display = 'none');

  const key = typeof selectedJmsRowId !== 'undefined' ? selectedJmsRowId : 'default';
  const poNo = window.selectedJmsPoNo;
  const siteId = window.selectedJmsSiteId;

  if (poNo && typeof NexusApi !== 'undefined' && NexusApi.commercial?.jms?.getDocuments) {
    try {
      const docsFromApi = await NexusApi.commercial.jms.getDocuments(poNo, siteId);
      if (Array.isArray(docsFromApi)) {
        jmsDocumentsMap[key] = docsFromApi.map(d => ({
          id: d.id,
          docType: d.docType,
          docDetails: d.docDetails,
          docName: d.docName,
          selected: false
        }));
      }
    } catch (err) {
      console.warn('Could not load documents from API:', err);
    }
  }

  renderJmsDocumentsTable();
  if (addCard) addCard.style.display = 'none';
  panel.style.display = 'block';
  overlay.style.display = 'flex';
};

window.closeJmsDocumentsModal = function() {
  const overlay = document.getElementById('sideFormOverlay');
  const panel = document.getElementById('jmsDocumentsPanel');
  const addCard = document.getElementById('addJmsDocumentCard');
  if (panel) panel.style.display = 'none';
  if (addCard) addCard.style.display = 'none';
  if (overlay) overlay.style.display = 'none';
};

window.renderJmsDocumentsTable = function() {
  const tbody = document.getElementById('tbodyJmsDocuments');
  const btnDelete = document.getElementById('btnJmsDocDelete');
  if (!tbody) return;

  const docs = getJmsDocuments(typeof selectedJmsRowId !== 'undefined' ? selectedJmsRowId : 'default');
  const hasSelected = docs.some(d => d.selected);
  if (btnDelete) {
    btnDelete.style.display = hasSelected ? 'inline-flex' : 'none';
  }

  if (docs.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="4" style="text-align: center; padding: 36px; color: #64748b; font-size: 0.95rem;">No documents added yet. Click + to add a document.</td>
      </tr>
    `;
    return;
  }

  tbody.innerHTML = docs.map(doc => {
    return `
      <tr data-doc-id="${doc.id}" style="border-bottom: 1px solid #e2e8f0; transition: background 0.15s ease;">
        <!-- 1. Select: Circle radio button -->
        <td style="width: 60px; min-width: 60px; max-width: 60px; text-align: center !important; vertical-align: middle; padding: 10px 6px;">
          <div class="circular-radio-btn" onclick="toggleJmsDocumentSelect('${doc.id}')" style="width: 18px; height: 18px; border-radius: 50%; border: 2px solid ${doc.selected ? '#0454e4' : '#94a3b8'}; background: ${doc.selected ? '#0454e4' : '#ffffff'}; margin: 0 auto; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.15s ease;" title="${doc.selected ? 'Unselect' : 'Select'}">
            ${doc.selected ? '<div style="width: 6px; height: 6px; border-radius: 50%; background: #ffffff;"></div>' : ''}
          </div>
        </td>
        <!-- 2. Document Type: 20ch & left -->
        <td style="width: 20ch; min-width: 20ch; max-width: 20ch; text-align: left !important; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; vertical-align: middle; padding: 10px 8px; color: #1e293b;" title="${(doc.docType || '').replace(/"/g, '&quot;')}">
          ${doc.docType || ''}
        </td>
        <!-- 3. Document Details: 20ch & left -->
        <td style="width: 20ch; min-width: 20ch; max-width: 20ch; text-align: left !important; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; vertical-align: middle; padding: 10px 8px; color: #475569;" title="${(doc.docDetails || '').replace(/"/g, '&quot;')}">
          ${doc.docDetails || ''}
        </td>
        <!-- 4. Document Name: 20ch & left -->
        <td style="width: 20ch; min-width: 20ch; max-width: 20ch; text-align: left !important; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; vertical-align: middle; padding: 10px 8px; color: #0454e4; font-weight: 500;" title="${(doc.docName || '').replace(/"/g, '&quot;')}">
          <span style="color: #0454e4; text-decoration: underline; text-underline-offset: 2px; cursor: pointer;" onclick="downloadJmsDocument('${doc.id}', '${(doc.docName || '').replace(/'/g, "\\'")}')">${doc.docName || ''}</span>
        </td>
      </tr>
    `;
  }).join('');
};

window.downloadJmsDocument = function(docId, docName) {
  if (typeof docId === 'number' || !isNaN(Number(docId))) {
    const apiBase = (typeof getCommercialApiBaseUrl === 'function') 
      ? getCommercialApiBaseUrl() 
      : ((typeof window !== 'undefined' && window.NexusApi && window.NexusApi.baseUrl) ? window.NexusApi.baseUrl : 'http://127.0.0.1:8000/api/v1');
    window.open(`${apiBase}/commercial/jms/documents/${docId}/download`, '_blank');
  } else {
    showToast(`Viewing ${docName}`);
  }
};

window.toggleJmsDocumentSelect = function(docId) {
  const key = typeof selectedJmsRowId !== 'undefined' ? selectedJmsRowId : 'default';
  const docs = getJmsDocuments(key);
  const doc = docs.find(d => String(d.id) === String(docId));
  if (doc) {
    doc.selected = !doc.selected;
    renderJmsDocumentsTable();
  }
};

window.deleteSelectedJmsDocuments = async function() {
  const key = typeof selectedJmsRowId !== 'undefined' ? selectedJmsRowId : 'default';
  const docs = getJmsDocuments(key);
  const selectedDocs = docs.filter(d => d.selected);

  if (selectedDocs.length === 0) {
    showToast('Please select at least one document to delete.');
    return;
  }

  for (const doc of selectedDocs) {
    if (typeof doc.id === 'number' && typeof NexusApi !== 'undefined' && NexusApi.commercial?.jms?.deleteDocument) {
      try {
        await NexusApi.commercial.jms.deleteDocument(doc.id);
      } catch (err) {
        console.error('Failed to delete doc:', err);
      }
    }
  }

  jmsDocumentsMap[key] = docs.filter(d => !d.selected);
  renderJmsDocumentsTable();
  showToast(`Deleted ${selectedDocs.length} document${selectedDocs.length > 1 ? 's' : ''}`);
};

window.openAddJmsDocumentModal = function() {
  const panel = document.getElementById('jmsDocumentsPanel');
  const addCard = document.getElementById('addJmsDocumentCard');
  if (panel) panel.style.display = 'none';
  if (addCard) {
    // Reset form
    const selType = document.getElementById('inpJmsDocType');
    const inpDetails = document.getElementById('inpJmsDocDetails');
    const inpName = document.getElementById('inpJmsDocName');
    if (selType) {
      selType.value = '';

      // Check selected project's projectType: show HOTO and NOC only for 'New Build'
      const parentInDataset = (typeof currentDataset !== 'undefined' && Array.isArray(currentDataset))
        ? currentDataset.find(r => String(r.id) === String(selectedJmsRowId) || (r.poNo && r.poNo === window.selectedJmsPoNo))
        : null;
      const parentInJms = (typeof commercialJmsData !== 'undefined' && Array.isArray(commercialJmsData))
        ? commercialJmsData.find(r => String(r.id) === String(selectedJmsRowId) || (r.poNo && r.poNo === window.selectedJmsPoNo))
        : null;
      const parentRow = parentInDataset || parentInJms;
      const projType = (parentRow && parentRow.projectType) || window.selectedJmsProjectType || '';
      const isNewBuild = String(projType).trim().toLowerCase() === 'new build';

      let optHoto = selType.querySelector('option[value="HOTO"]');
      let optNoc = selType.querySelector('option[value="NOC"]');

      if (isNewBuild) {
        if (!optHoto) {
          optHoto = document.createElement('option');
          optHoto.value = 'HOTO';
          optHoto.textContent = 'HOTO';
          selType.appendChild(optHoto);
        }
        if (!optNoc) {
          optNoc = document.createElement('option');
          optNoc.value = 'NOC';
          optNoc.textContent = 'NOC';
          selType.appendChild(optNoc);
        }
      } else {
        if (optHoto) optHoto.remove();
        if (optNoc) optNoc.remove();
      }
    }
    if (inpDetails) inpDetails.value = '';
    if (inpName) inpName.value = '';
    addCard.style.display = 'block';
  }
};

window.closeAddJmsDocumentModal = function() {
  const panel = document.getElementById('jmsDocumentsPanel');
  const addCard = document.getElementById('addJmsDocumentCard');
  if (addCard) addCard.style.display = 'none';
  if (panel) panel.style.display = 'block';
};

window.triggerJmsDocPdfUpload = function() {
  const filePicker = document.getElementById('inpJmsDocPdfFilePicker');
  if (filePicker) filePicker.click();
};

window.handleJmsDocPdfFileSelected = function(input) {
  if (input && input.files && input.files[0]) {
    const file = input.files[0];
    const inpName = document.getElementById('inpJmsDocName');
    const inpDetails = document.getElementById('inpJmsDocDetails');
    if (inpName) inpName.value = file.name;
    if (inpDetails && !inpDetails.value) {
      const typeVal = document.getElementById('inpJmsDocType') ? document.getElementById('inpJmsDocType').value : 'Document';
      inpDetails.value = `${typeVal} Upload`;
    }
    showToast(`PDF selected: ${file.name}`);
  }
};

window.saveJmsDocument = async function() {
  const selType = document.getElementById('inpJmsDocType');
  const inpDetails = document.getElementById('inpJmsDocDetails');
  const inpName = document.getElementById('inpJmsDocName');
  const filePicker = document.getElementById('inpJmsDocPdfFilePicker');

  const docType = selType ? (selType.value || 'Survey report') : 'Survey report';
  const docDetails = inpDetails ? (inpDetails.value.trim() || `${docType} Details`) : `${docType} Details`;
  let docName = inpName ? inpName.value.trim() : '';
  if (!docName) {
    docName = `${docType.replace(/\s+/g, '_')}_${Date.now().toString().slice(-4)}.pdf`;
  } else if (!docName.toLowerCase().endsWith('.pdf')) {
    docName += '.pdf';
  }

  const key = typeof selectedJmsRowId !== 'undefined' ? selectedJmsRowId : 'default';
  const poNo = window.selectedJmsPoNo;
  const siteId = window.selectedJmsSiteId;

  if (poNo && typeof NexusApi !== 'undefined' && NexusApi.commercial?.jms?.uploadDocument) {
    try {
      const formData = new FormData();
      formData.append('po_no', poNo);
      if (siteId) formData.append('site_id', siteId);
      formData.append('doc_type', docType);
      formData.append('doc_details', docDetails);

      if (filePicker && filePicker.files && filePicker.files[0]) {
        formData.append('file', filePicker.files[0]);
      } else {
        const dummyPdf = new Blob(['%PDF-1.4 Default JMS Document content'], { type: 'application/pdf' });
        formData.append('file', dummyPdf, docName);
      }

      const uploadedDoc = await NexusApi.commercial.jms.uploadDocument(formData);
      if (uploadedDoc) {
        if (!jmsDocumentsMap[key]) jmsDocumentsMap[key] = [];
        jmsDocumentsMap[key].push({
          id: uploadedDoc.id,
          docType: uploadedDoc.docType,
          docDetails: uploadedDoc.docDetails,
          docName: uploadedDoc.docName,
          selected: false
        });
      }
    } catch (err) {
      console.error('Failed to upload document:', err);
      showToast('Error uploading document to server.');
      return;
    }
  } else {
    const docs = getJmsDocuments(key);
    docs.push({
      id: `jmsdoc-${Date.now()}`,
      docType: docType,
      docDetails: docDetails,
      docName: docName,
      selected: false
    });
    jmsDocumentsMap[key] = docs;
  }

  closeAddJmsDocumentModal();
  renderJmsDocumentsTable();
  showToast(`Document "${docName}" added successfully!`);
};

