window.copyPoAmendItemCode = function(code) {
  if (!code) return;
  if (navigator.clipboard) {
    navigator.clipboard.writeText(code).then(() => {
      showToast(`Copied Item Code: ${code}`);
    }).catch(() => {
      showToast(`Copied Item Code: ${code}`);
    });
  } else {
    showToast(`Copied Item Code: ${code}`);
  }
};

